class Solution {public:long long solve(vector<int> values){int n=values.size();vector<int> left(n),right(n),stack;for(int i=0;i<n;i++){while(!stack.empty()&&values[stack.back()]>=values[i])stack.pop_back();left[i]=i-(stack.empty()?-1:stack.back());stack.push_back(i);}stack.clear();for(int i=n-1;i>=0;i--){while(!stack.empty()&&values[stack.back()]>values[i])stack.pop_back();right[i]=(stack.empty()?n:stack.back())-i;stack.push_back(i);}long long total=0;for(int i=0;i<n;i++)total+=1LL*values[i]*left[i]*right[i];return total;}};